def main():
    os.makedirs(DEST, exist_ok=True)
    with open(os.path.join(DEST, "listings.csv"), "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["file", "title", "main_tag", "tags", "description"])
        for slug, (title, main, tags, desc) in POD.items():
            w.writerow([f"{slug}.png", title, main, tags, desc])
    lines = ["# Print-on-demand listings, batch 2 (Redbubble and Teepublic)", "",
             f"{len(POD)} new designs. Each has two files with the same name: `light-shirts/` (navy ink, for white, cream, pastel and heather products) and `dark-shirts/` (cream ink, for black, navy and dark products). Upload the light version first; on Teepublic you can add the dark version as the alternate design for dark garments. Files are 4500x5400 transparent PNGs.", ""]
    for i, (slug, (title, main, tags, desc)) in enumerate(POD.items(), 1):
        lines += [f"## {i}. {title}", f"- File: `{slug}.png`", f"- Title: {title}", f"- Main tag (Teepublic): {main}", f"- Tags: {main}, {tags}", f"- Description: {desc}", ""]
    open(os.path.join(DEST, "LISTINGS.md"), "w").write("\n".join(lines))


if __name__ == "__main__":
    main()
